import json, subprocess, copy, math

def base_model(C=2,E=1,le=None,ge=None,K=1,cw=None,cb=None,cshift=None,dw=None,db=None):
    if le is None:
        le=[[i] for i in range(16)]
    if ge is None:
        ge=[[0] for _ in range(16)]
    if cw is None:
        cw=[[[1,0]]]
    if cb is None:
        cb=[0]
    if cshift is None:
        cshift=[0]
    if dw is None:
        dw=[[0],[1]]
    if db is None:
        db=[0,0]
    return dict(classes=C,embedding_dim=E,length_embedding=le,gap_embedding=ge,
                kernel=K,conv_weights=cw,conv_bias=cb,conv_shift=cshift,
                dense_weights=dw,dense_bias=db)

def run(doc):
    p=subprocess.run(['python3','submission/main.py'],input=json.dumps(doc).encode(),
                     stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    return p.returncode, p.stdout.decode(), p.stderr.decode()

def show(name,doc):
    rc,out,err=run(doc)
    print("====",name,"rc",rc)
    try:
        o=json.loads(out)
    except Exception:
        print("BAD OUT",out[:200]); return
    print(json.dumps(o,indent=1))

# ---- Test superseded ----
cfg=dict(slots=1,window=1,idle_timeout=1000,len_quantum=1,gap_quantum=1,
         rate_num=1,rate_den=1,bucket_capacity=100,initial_tokens=100,
         pending_capacity=512,lanes=2,service=[10,1],fallback=0,
         time_edges=[0],count_edges=[0],probability=[[65536]])
doc=dict(version=1,config=cfg,model=base_model(),
         connections=[dict(id="a",slot=0,label=0,split="dev")],
         packets=[dict(time=0,connection="a",length=0,draw=0),
                  dict(time=1,connection="a",length=5,draw=0)])
show("superseded",doc)
PY
python3 tmp/gen_tests.py

